        if(job.hasNonNull("runtimeContainer")){existing=base.optional("/containers/"+job.path("runtimeContainer").asText()+"/json");if(!operation.equals(job.path("runtimeOperation"))){require(existing==null||!existing.path("State").path("Running").asBoolean(),"A different installer operation is still running");existing=null;job.remove(List.of("runtimeContainer","runtimeName"));}}
