        while(System.nanoTime()<end){if(!ignoreCancellation)base.cancelled(job);else require(!base.closing(),"Platform closing");JsonNode state=base.docker.call("GET","/containers/"+id+"/json").path("State");update(job,project);if(System.nanoTime()-lastLog>Duration.ofSeconds(5).toNanos()){job.put("installerLog",logs(job,privateState));base.save(job);lastLog=System.nanoTime();}if(!state.path("Running").asBoolean()){job.put("installerLog",logs(job,privateState));base.save(job);require(state.path("ExitCode").asInt()==0,"Native installer failed; inspect retained redacted installer logs");return;}Thread.sleep(1000);}
